@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_structure_template_data_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_structure_template_data_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
